/**
 * Cele ataków bohatera w świecie (wrogowie, boss, kokony, purchawki, ukryta komnata, urny). Scena wie, co jest
 * na piętrze; `attacker` to bohater, który atakuje — boss jest nietykalny dla ataków spoza areny (krok 86).
 */
export interface HeroStrikeTargets {
  /** Cios wręcz; zwraca liczbę trafionych stworzeń (do Wampirzego kła). */
  melee(swing: MeleeSwing, attacker: Player): number;
  /** Tyknięcie promienia; zwraca liczbę trafionych stworzeń (do Wampirzego kła, krok 180). */
  beam(beam: BeamStrike, attacker: Player): number;
  /** Rozprysk kuli, fala uderzeniowa i Supernowa — wrogowie i boss. */
  splash(strike: OrbSplash, attacker: Player): void;
  dash(sweep: DashSweep, alreadyHit: Set<object>, attacker: Player): void;
}

export interface HeroCombatDeps {
  readonly scene: Phaser.Scene;
  readonly player: Player;
  readonly hero: HeroId;
  /** Przedmioty tego bohatera (co-op: każdy zbiera dla siebie). */
  readonly items: () => readonly ItemId[];
  readonly floorEffects: FloorModifierEffects;
  readonly floorNumber: number;
  readonly effects: CombatEffects;
  readonly playerShots: PlayerShotManager;
  readonly walls: Phaser.Tilemaps.TilemapLayer;
  /** Plansza piętra — piorun Elektrycznej strzały i Iskrownika nie przechodzi przez ściany (krok 151). */
  readonly floor: DungeonFloor;
  readonly strikes: HeroStrikeTargets;
  /** Cele totemu: żywi, widoczni wrogowie i boss z pomocnikami. */
  readonly aimTargets: () => Iterable<AimTarget>;
}

/** Barwa liczb obrażeń od trucizny nad bohaterem — zieleń jadu (krok 27). */
const POISON_TEXT_COLOR = '#8cff6a';

/**
 * Walka jednego bohatera (co-op, etap C2; wcześniej w `GameScene`): jego ataki (cios, strzał, kule, strzały,
 * promień, fala, Burzowy pęd), Wampirzy kieł i ultimate. Solo — jeden taki obiekt, co-op — po jednym na gracza.
 */
export class HeroCombat {
  readonly ultimates: UltimateManager;
  /** Cele trafione Burzowym pędem w dashu o numerze `dashHitsFor`. */
  private dashHits = new Set<object>();
  private dashHitsFor = -1;
  /** Wampirzy kieł: przerwa między leczeniami (krok 93). */
  private readonly healCooldown = new Timer();
  /** Wampirzy kieł: sufit leczenia na sekundę (krok 93). */
  private readonly healBudget = new HealBudget();
  private beamGfx: Phaser.GameObjects.Graphics | null = null;
  /** Tyknięcia bieżącego promienia (od zapalenia) — co `pulseEveryTicks` impuls (krok 180). */
  private beamTicksDone = 0;
  /** Ostatni dash, który już zabrzmiał (krok 116). */
  private dashSoundFor = -1;
  /** Teleport, po którym czekamy na błysk przybycia (krok 181); -1 = żaden. */
  private blinkArrivalFor = -1;
  /** Krok 150: przemiany przedmiotów. */
  private readonly ramp = new AttackRamp();
  private rampStep = 0;
  private attacksMade = 0;
  private nextSparkAt = 0;
  private readonly stormTrail = new StormTrail();
  private readonly evolutionView: HeroEvolutionView;

  constructor(private readonly deps: HeroCombatDeps) {
    this.ultimates = new UltimateManager({
      scene: deps.scene,
      player: deps.player,
      effects: deps.effects,
      playerShots: deps.playerShots,
      blast: (strike) => deps.strikes.splash(strike, deps.player),
      targets: deps.aimTargets,
      onRageChanged: () => deps.player.applyLoadout(this.loadout()),
      floorNumber: deps.floorNumber,
    });
    this.evolutionView = new HeroEvolutionView(deps.scene);
    deps.scene.events.once(Phaser.Scenes.Events.SHUTDOWN, () => this.evolutionView.destroy());
  }

  get player(): Player {
    return this.deps.player;
  }

  get hero() {
    return HERO_DEFINITIONS[this.deps.hero];
  }

  /** Statystyki bohatera z przedmiotów, modyfikatora piętra i szału. */
  loadout(): PlayerLoadout {
    const now = this.deps.scene.time.now;
    const ramp = this.ramp.bonus(now, this.deps.player.effects.evolved.attackRamp);
    return heroLoadout(this.deps.hero, this.deps.items(), this.deps.floorEffects, this.ultimates.isRaging(now), ramp);
  }

  /** Jedna klatka bohatera: ruch, ataki i ultimate z akcji gracza. */
  tick(actions: PlayerActions, time: number): void {
    const { player, effects, playerShots } = this.deps;
    const turn = player.tick(actions, time);
    if (turn.poisonDamage > 0) {
      effects.floatingText(player.x, player.y - player.radius, `-${turn.poisonDamage}`, POISON_TEXT_COLOR);
    }
    if (turn.struck) this.resolveStrike(time);
    if (turn.shot) {
      const { x, y, combatConfig } = player;
      // Kołczan bez dna (krok 150): strzał z ładunku leci podwójnie, lekko rozchylony.
      const { twinShot, twinSpreadDeg } = player.effects.evolved;
      const base = Math.atan2(turn.shot.y, turn.shot.x);
      const spread = Phaser.Math.DegToRad(twinSpreadDeg) / 2;
      const angles = twinShot ? [base - spread, base + spread] : [base];
      for (const angle of angles) {
        playerShots.fire({ x, y }, { x: Math.cos(angle), y: Math.sin(angle) }, combatConfig.ranged, player.effects, undefined, player, { homing: BARBARIAN_SHOT_HOMING });
      }
      sound.play(SoundCue.ArrowShot, player);
    }
    if (turn.orb) this.fireOrb(turn.orb);
    if (turn.ultimate) this.ultimates.use(turn.ultimate, time);
    if (turn.nova) this.castNova(time);
    if (turn.arrow) this.fireArrow(turn.arrow.direction, turn.arrow.strong);
    if (turn.struck || turn.orb || turn.arrow) this.afterMainAttack(time);
    if (turn.volley) this.fireVolley(turn.volley);
    this.updateBeam(turn.beam, turn.beamTicks, turn.beamCharge, time);
    sound.hold(LoopCue.Beam, player, turn.beam && !player.isDead);
    if (player.dashId !== this.dashSoundFor && player.isDashing(time)) {
      this.dashSoundFor = player.dashId;
      sound.play(SoundCue.Dash, player);
      // Krok 181: teleport Czarodziejki — błysk w miejscu startu, drugi po przybyciu.
      if (player.combatConfig.dash.blink) {
        this.deps.effects.blink(player.x, player.y);
        this.blinkArrivalFor = player.dashId;
      }
    }
    if (this.blinkArrivalFor === player.dashId && !player.isDashing(time)) {
      this.blinkArrivalFor = -1;
      this.deps.effects.blink(player.x, player.y);
    }
    this.ultimates.update(time);
    this.resolveDashStrike(time);
    this.updateEvolutions(time);
  }

  /**
   * Krok 150: atak główny (cios, kula, strzała z łuku; od kroku 180 impuls promienia) — Rozpęd liczy serię, a co 3. atak z Falą ostrza
   * wylatuje półksiężyc.
   */
  private afterMainAttack(now: number): void {
    const { player } = this.deps;
    const { attackRamp, bladeWave } = player.effects.evolved;
    if (attackRamp) this.ramp.onAttack(now, attackRamp);
    if (!bladeWave) return;
    this.attacksMade++;
    if (this.attacksMade % bladeWave.every !== 0) return;
    const angle = player.getAimAngle();
    const damage = Math.max(1, Math.round(this.mainAttackDamage() * bladeWave.damageFraction));
    this.deps.playerShots.fire(
      { x: player.x, y: player.y },
      { x: Math.cos(angle), y: Math.sin(angle) },
      { damage, knockback: bladeWave.knockback, projectileSpeed: bladeWave.speed, projectileLifetimeMs: bladeWave.lifetimeMs, projectileRadius: bladeWave.radius },
      player.effects,
      { texture: ensureCrescentTexture(this.deps.scene), status: player.effects.meleeStatus, vampiric: false, magic: true },
      player,
      { pierce: 99 },
    );
    sound.play(SoundCue.SwordSwing, player);
  }

  /** Obrażenia ataku głównego bohatera (podstawa fali ostrza). */
  private mainAttackDamage(): number {
    const { player } = this.deps;
    return player.archeryConfig?.bow.damage ?? player.sorceryConfig?.orbs.damage ?? player.combatConfig.meleeDamage;
  }

  /** Krok 150: Rozpęd, Iskrownik, Ślad burzy i wygląd przemian — co klatkę. */
  private updateEvolutions(now: number): void {
    const { player } = this.deps;
    const evolved = player.effects.evolved;
    // Rozpęd: zmiana stopnia przelicza tempo ataku (bez zerowania ciosu ani dasha).
    const step = this.ramp.step(now, evolved.attackRamp);
    if (step !== this.rampStep) {
      this.rampStep = step;
      player.applyLoadout(this.loadout());
    }
    if (evolved.sparker && !player.isDead && now >= this.nextSparkAt) this.fireSparker(now, evolved.sparker);
    if (evolved.stormTrail) {
      this.stormTrail.track({ x: player.x, y: player.y + player.radius / 2 }, player.isDashing(now), now, evolved.stormTrail);
      const points = this.stormTrail.strike(now, evolved.stormTrail);
      if (points.length > 0) {
        const hit = new Set<object>();
        for (const point of points) this.deps.strikes.dash({ center: point.at, radius: evolved.stormTrail.radius, damage: evolved.stormTrail.damage, now }, hit, player);
      }
    }
    this.evolutionView.draw(player, now, {
      sparker: evolved.sparker !== null,
      shield: player.shieldHp,
      shieldMax: evolved.bloodShieldMax,
      trail: evolved.stormTrail ? this.stormTrail.alive : [],
      dead: player.isDead,
    });
  }

  /** Iskrownik (Elektryczna strzała ×3): piorun z kuli nad ramieniem w najbliższego wroga i dalej łańcuchem. */
  private fireSparker(now: number, sparker: NonNullable<PlayerLoadout['effects']['evolved']['sparker']>): void {
    const { player } = this.deps;
    const targets = [...this.deps.aimTargets()];
    const from = HeroEvolutionView.sparkerPoint(player, now);
    const canLink = sparkLinkRule(this.deps.floor, player, TILE_SIZE);
    const [first] = chainTargets(player, targets, 1, sparker.range, undefined, canLink);
    if (!first) return;
    this.nextSparkAt = now + sparker.intervalMs;
    const chain = [first, ...chainTargets(first, targets, sparker.chains, sparker.chainRange, (t) => t === first, canLink)];
    this.strikeChain(from, chain, sparker.damage, now);
    sound.play(SoundCue.OrbSplash, from);
  }

  /** Piorun od `from` przez kolejne cele: każdy dostaje `damage` raz. */
  private strikeChain(from: Vector2, chain: readonly { readonly x: number; readonly y: number; readonly radius: number }[], damage: number, now: number): void {
    const hit = new Set<object>();
    let at = from;
    for (const target of chain) {
      drawBolt(this.deps.scene, at, target);
      this.deps.strikes.dash({ center: { x: target.x, y: target.y }, radius: Math.max(2, target.radius / 2), damage, now }, hit, this.deps.player);
      at = target;
    }
  }

  /** Trafienie pocisku tego bohatera: kieł leczy za stworzenie, kula i strzała mają rozprysk magii. */
  afterShotHit(shot: { readonly position: Vector2; readonly damage: number; readonly vampiric?: boolean; readonly magic?: boolean }, target: object, creature: boolean, now: number): void {
    if (creature && shot.vampiric) this.tryVampireHeal(now);
    if (shot.magic) this.orbSplash(shot.position, shot.damage, target, now);
    // Elektryczna strzała (krok 150): piorun przeskakuje z trafionego stworzenia na najbliższych sąsiadów.
    const chain = this.deps.player.effects.evolved.chain;
    if (creature && chain && 'x' in target && 'y' in target) {
      const origin = { x: Number(target.x), y: Number(target.y) };
      const near = (t: Vector2): boolean => Math.hypot(t.x - origin.x, t.y - origin.y) < 1;
      const jumps = chainTargets(origin, [...this.deps.aimTargets()], chain.targets, chain.range, near, sparkLinkRule(this.deps.floor, this.deps.player, TILE_SIZE));
      if (jumps.length > 0) this.strikeChain(origin, jumps, Math.max(1, Math.round(shot.damage * chain.damageFraction)), now);
    }
  }

  /** Kula Czarodziejki wylatuje z kryształu; niesie wszystkie efekty broni z przedmiotów. */
  private fireOrb(direction: Vector2): void {
    const { player } = this.deps;
    const orbs = player.sorceryConfig?.orbs;
    if (!orbs) return;
    const { effects } = player;
    const origin = crystalPoint(player, Math.atan2(direction.y, direction.x), orbs.forwardOffset, orbs.sideOffset);
    sound.play(SoundCue.OrbThrow, player);
    this.deps.playerShots.fire(
      origin,
      direction,
      {
        damage: orbs.damage,
        knockback: orbs.knockback,
        projectileSpeed: orbs.speed,
        projectileLifetimeMs: orbs.lifetimeMs,
        projectileRadius: orbs.radius,
      },
      effects,
      {
        texture: SPRITE_SHEETS[SORCERESS_ORB_VISUAL.sheet].key,
        animation: animationKey(SORCERESS_ORB_VISUAL.sheet, SORCERESS_ORB_VISUAL.animation),
        status: { ...effects.shotStatus, ...effects.meleeStatus },
        vampiric: effects.meleeHeal > 0,
        magic: true,
      },
      player,
    );
  }

  /**
   * Strzała łucznika z łuku (krok 82; ciągły ostrzał od kroku 97): mocna strzała serii przebija.
   * Łuk to broń główna, więc strzała niesie wszystkie efekty broni (strzał + cios), jak kula Czarodziejki,
   * i trafia upiory zasadzki (domyślna decyzja z kroku 82, do oceny właściciela).
   */
  private fireArrow(direction: Vector2, strong: boolean): void {
    const { player } = this.deps;
    const archery = player.archeryConfig;
    if (!archery) return;
    const { bow } = archery;
    const spec = arrowSpec(bow, strong);
    sound.play(spec.strong ? SoundCue.ArrowStrong : SoundCue.ArrowShot, player);
    const origin = crystalPoint(player, Math.atan2(direction.y, direction.x), bow.forwardOffset, bow.sideOffset);
    this.deps.playerShots.fire(
      origin,
      direction,
      {
        damage: spec.damage,
        knockback: spec.knockback,
        projectileSpeed: spec.speed,
        projectileLifetimeMs: bow.lifetimeMs,
        projectileRadius: bow.radius,
      },
      player.effects,
      this.arrowLook(direction, spec.strong, spec.pierce),
      player,
    );
  }

  /** Salwa łucznika (PPM): wachlarz strzał z obrażeniami i lotem ładunków strzału (`combat.ranged`). */
  private fireVolley(aim: Vector2): void {
    const { player } = this.deps;
    const archery = player.archeryConfig;
    if (!archery) return;
    const { bow, volley } = archery;
    const angle = Math.atan2(aim.y, aim.x);
    const origin = crystalPoint(player, angle, bow.forwardOffset, bow.sideOffset);
    sound.play(SoundCue.Volley, player);
    for (const direction of volleyDirections(angle, volley.arrows, volley.spreadDeg)) {
      this.deps.playerShots.fire(origin, direction, player.combatConfig.ranged, player.effects, this.arrowLook(direction, false, 0), player);
    }
  }

  private arrowLook(direction: Vector2, strong: boolean, extraPierce: number): ShotLook {
    const { effects } = this.deps.player;
    const sheet = ARCHER_ARROW_VISUAL.sheet;
    return {
      texture: SPRITE_SHEETS[sheet].key,
      animation: animationKey(sheet, strong ? ARCHER_ARROW_VISUAL.fullAnimation : ARCHER_ARROW_VISUAL.animation, facingDirection(direction) ?? 0),
      status: { ...effects.shotStatus, ...effects.meleeStatus },
      vampiric: effects.meleeHeal > 0,
      magic: true,
      extraPierce,
    };
  }

  /** Rozprysk kuli (krok 50): sąsiedzi trafionego dostają ułamek obrażeń; wrogowie, pajączki z bossa i boss. */
  private orbSplash(at: Vector2, orbDamage: number, mainTarget: object, now: number): void {
    const { player } = this.deps;
    const splash = player.sorceryConfig?.orbs.splash;
    if (!splash) return;
    const strike: OrbSplash = {
      center: { x: at.x, y: at.y },
      radius: splash.radius,
      damage: splashDamage(orbDamage, splash.damageFraction),
      now,
      source: { x: player.x, y: player.y },
      exclude: mainTarget,
    };
    this.deps.strikes.splash(strike, player);
    this.deps.effects.splash(at.x, at.y, splash.radius);
    sound.play(SoundCue.OrbSplash, at);
  }

  /**
   * Fala uderzeniowa Czarodziejki (krok 97): przy rzucie ostatniej kuli serii rani i odpycha wrogów wokół niej.
   * Magia (trafia upiory), bez efektów przedmiotów — jak rozprysk kuli.
   */
  private castNova(now: number): void {
    const { player } = this.deps;
    const nova = player.sorceryConfig?.orbs.nova;
    if (!nova) return;
    const center = { x: player.x, y: player.y };
    const strike: OrbSplash = { center, radius: nova.radius, damage: nova.damage, knockback: nova.knockback, now, source: center, exclude: null };
    this.deps.strikes.splash(strike, player);
    this.deps.effects.nova(center.x, center.y, nova.radius);
    sound.play(SoundCue.Nova, center);
  }

  /**
   * Promień Czarodziejki: rysunek co klatkę, obrażenia w klatkach z tickiem; zatrzymuje się na ścianie.
   * Krok 181 — Wyrwa: obrażenia i szerokość rosną wykładniczo z czasem świecenia (`beamGrowth`).
   */
  private updateBeam(active: boolean, ticks: number, charge: number, now: number): void {
    const { player } = this.deps;
    const config = player.sorceryConfig?.beam;
    if (!active || !config) {
      this.beamGfx?.clear();
      this.beamTicksDone = 0;
      return;
    }
    const angle = player.getAimAngle();
    const dir = { x: Math.cos(angle), y: Math.sin(angle) };
    const from = crystalPoint(player, angle, config.forwardOffset, config.sideOffset);
    const walls = this.deps.walls;
    const blocked = (p: Vector2): boolean => walls.getTileAtWorldXY(p.x, p.y)?.collides ?? false;
    const length = blocked(from) ? 0 : beamReach(from, angle, config.range, blocked);
    const to = { x: from.x + dir.x * length, y: from.y + dir.y * length };
    const halfWidth = config.halfWidth * beamGrowth(charge, config.growth.widthMultiplier);
    const damage = Math.max(1, Math.round(config.damagePerTick * beamGrowth(charge, config.growth.damageMultiplier)));
    this.drawBeam(from, to, halfWidth);
    dynamicLights.beam(this.deps.scene, from, to);
    for (let i = 0; i < ticks; i++) {
      // Krok 180: impuls niesie statusy przedmiotów, leczy kłem i liczy się jako atak główny (Rozpęd, Fala ostrza).
      const pulse = isBeamPulse(this.beamTicksDone++, config.pulseEveryTicks);
      const beam: BeamStrike = {
        from,
        to,
        halfWidth,
        damage,
        knockback: config.knockback,
        now,
        source: { x: player.x, y: player.y },
        ...(pulse && { status: beamPulseStatus(player.effects) }),
      };
      const hits = this.deps.strikes.beam(beam, player);
      if (!pulse) continue;
      if (hits > 0) this.tryVampireHeal(now);
      this.afterMainAttack(now);
    }
  }

  /**
   * Wyrwa (krok 181) w fiolecie Czarodziejki: trzy warstwy grubości zależnej od `halfWidth` (rośnie z narastaniem),
   * kula energii u kryształu i na końcu; jądro migocze tylko wizualnie (Math.random wolno).
   */
  private drawBeam(from: Vector2, to: Vector2, halfWidth: number): void {
    const gfx = this.beamGfx ?? (this.beamGfx = this.deps.scene.add.graphics().setDepth(RENDER_DEPTH.slash));
    const C = SORCERY_COLORS;
    const outer = Math.max(3, Math.round(halfWidth * 2));
    const mid = Math.max(2, Math.round(halfWidth * 1.25));
    const core = Math.max(1, Math.round(halfWidth * 0.5)) + (Math.random() < 0.5 ? 0 : 1);
    gfx.clear();
    gfx.lineStyle(outer, C.deep, 1).lineBetween(from.x, from.y, to.x, to.y);
    gfx.lineStyle(mid, C.base, 1).lineBetween(from.x, from.y, to.x, to.y);
    gfx.lineStyle(core, C.core, 1).lineBetween(from.x, from.y, to.x, to.y);
    gfx.fillStyle(C.base, 1).fillCircle(to.x, to.y, Math.max(3, halfWidth * 1.1));
    gfx.fillStyle(C.light, 1).fillCircle(to.x, to.y, Math.max(2, halfWidth * 0.6));
    gfx.fillStyle(C.base, 1).fillCircle(from.x, from.y, Math.max(2, halfWidth * 0.9));
    gfx.fillStyle(C.core, 1).fillCircle(from.x, from.y, Math.max(1, halfWidth * 0.45));
  }

  /** Wampirzy kieł: leczenie za trafienie (raz na cios lub kulę), najwyżej raz na meleeHealCooldownMs. */
  private tryVampireHeal(now: number): void {
    const { player, effects } = this.deps;
    const { meleeHeal, meleeHealCooldownMs, meleeHealMaxPerSec } = player.effects;
    // Krwawa tarcza (krok 150): przy pełnym HP leczenie buduje tarczę, do limitu.
    const shielding = player.health.isFull && player.shieldHp < player.effects.evolved.bloodShieldMax;
    if (meleeHeal <= 0 || (player.health.isFull && !shielding) || this.healCooldown.isActive(now)) return;
    this.healCooldown.start(now, meleeHealCooldownMs);
    const heal = this.healBudget.take(meleeHeal, now, meleeHealMaxPerSec);
    if (heal <= 0) return;
    if (shielding) {
      const added = player.addBloodShield(heal);
      if (added > 0) effects.floatingText(player.x, player.y - 14, `+${added}`, '#ff3a5a');
      return;
    }
    player.heal(heal);
    effects.floatingText(player.x, player.y - 14, `+${heal}`, '#ff6b8a');
  }

  private resolveStrike(now: number): void {
    const { player, effects } = this.deps;
    const combat = player.combatConfig;
    const swing: MeleeSwing = {
      origin: { x: player.x, y: player.y },
      angle: player.getAimAngle(),
      combat,
      now,
      status: player.effects.meleeStatus,
    };
    const arc = Phaser.Math.DegToRad(combat.meleeArcDeg);
    effects.slash(swing.origin.x, swing.origin.y, swing.angle, combat.meleeRange, arc);
    sound.play(SoundCue.SwordSwing, swing.origin);
    // Wampirzy kieł: leczenie za cios, który trafił wroga lub bossa (raz na cios, niezależnie od liczby celów).
    // Krok 93: kokony, purchawki i urny już nie leczą.
    if (this.deps.strikes.melee(swing, player) > 0) {
      this.tryVampireHeal(now);
      // Krok 167/171: cięższe ciosy barbarzyńcy — trafienie czuć w kamerze.
      if (combat.hitShake) screenFx.shake(this.deps.scene.cameras.main, combat.hitShake.durationMs, combat.hitShake.intensity);
    }
  }

  /** Burzowy pęd: w trakcie dasha bohater rani dotkniętych wrogów (każdego raz na dash). */
  private resolveDashStrike(now: number): void {
    const { player } = this.deps;
    const damage = player.effects.dashDamage;
    if (damage <= 0 || !player.isDashing(now)) return;
    if (this.dashHitsFor !== player.dashId) {
      this.dashHitsFor = player.dashId;
      this.dashHits = new Set();
    }
    const sweep = { center: { x: player.x, y: player.y }, radius: player.radius, damage, now };
    this.deps.strikes.dash(sweep, this.dashHits, player);
  }
}

/** Loadout bohatera: przedmioty, limity statystyk, modyfikator piętra, (barbarzyńca) szał i Rozpęd (krok 150). */
export function heroLoadout(hero: HeroId, items: readonly ItemId[], floorEffects: FloorModifierEffects, raging: boolean, rampBonus = 0): PlayerLoadout {
  const definition = HERO_DEFINITIONS[hero];
  const loadout = applyFloorToLoadout(computeHeroLoadout(definition, items, ITEM_DEFINITIONS, STAT_LIMITS, ITEM_EFFECTS, rampBonus), floorEffects);
  // Szał barbarzyńcy (krok 98) mnoży loadout na czas trwania.
  const { ultimate } = definition;
  return ultimate.kind === 'rage' && raging ? applyRage(loadout, ultimate) : loadout;
}
